  "{0}일 전": "{0}d ago",
  "프로젝트 폴더를 엽니다. 문서·그림·글꼴은 프로젝트 안에 상대 경로와 해시로 저장되어, 폴더를 통째로 옮겨도 그대로 열립니다.": "Open a project folder. Documents, images and fonts use relative paths and content hashes, so the whole folder can move between computers.",
  "InDesign 문서 가져오기…": "Import InDesign Document…",
  "최근 프로젝트": "Recent Projects",
  "아직 없습니다.": "No recent projects.",
  "최근 InDesign 문서 ": "Recent InDesign Documents ",
  "(프로젝트로 가져오기)": "(Import into a project)",
  "INDD·IDML 파일을 창에 끌어다 놓으면 열기 창이 뜹니다: 프로젝트로 가져오기, 또는 프로젝트 없이 읽기 전용으로 열기(PDF·패키지는 됨). 원본은 읽기만 하고 덮어쓰지 않습니다.": "Drop an INDD or IDML file here to import it into a project or open it read-only. PDF export and packaging are available in read-only mode. Source files are never overwritten.",
  "새 프로젝트": "New Project",
  "새 프로젝트를 만들 위치": "New Project Location",
  "프로젝트는 폴더 하나입니다. 맨 위에 folio.project를 만들고, 문서·그림·글꼴은 이 폴더 안에 상대 경로로 둡니다. NAS 동기화 폴더에 만들어도 됩니다.": "A project is a folder containing folio.project. Documents, images and fonts stay inside it with relative paths. You can use a folder synced to your NAS.",
