  "— 편집·저장 (.folio). 링크를 프로젝트 안으로 복사합니다": "— Edit and save as .folio. Links are copied into the project",
  "읽기 전용으로 열기": "Open Read-only",
  "— 프로젝트 없이 바로 봅니다": "— View directly without a project",
  "아무것도 저장하지 않고 프로젝트 폴더도 만들지 않습니다. 편집·저장은 할 수 없고, 사전 검사·링크 확인·분판 미리보기·PDF 내보내기·패키지는 됩니다. 고치고 싶어지면 나중에 같은 문서를 프로젝트로 가져오세요.": "No project folder is created and nothing is saved. Preflight, links, separations, PDF export and packaging are available. Import the document into a project when you want to edit it.",
