  "복사는 프로젝트의 임시 폴더에서 하고 마지막에 넣습니다. 취소하거나 실패하면 프로젝트에 아무것도 남지 않습니다.": "Files are staged in a temporary folder before being added to the project. Cancellation or failure leaves no partial import.",
