  "InDesign 교환": "InDesign Interchange",
  "링크는 이 컴퓨터의 실제 파일 위치로, Folio 정보(고유 ID·상대 경로·해시)는 folio.* 스크립트 레이블로 실어 보냅니다. Folio는 INDD를 직접 쓰지 않으니, INDD가 필요하면 이 IDML을 InDesign에서 열어 저장하세요.": "Links use their actual file locations on this computer. Folio IDs, relative paths and hashes are stored in folio.* script labels. To create an INDD file, open the exported IDML in InDesign and save it there.",
