  '자체 시작 번호': 'own start number',
  '빈 페이지 {0}쪽 추가': '{0} blank page(s) added',
  '.idml은 쓰지 않음': '.idml is not written',
  '페이지 {0}': 'pages {0}',
  '프로젝트 문서 목록을 책으로 저장합니다. 책은 Folio 형식(.foliobook)이며 문서의 프로젝트 상대 경로와 SHA-256을 기억합니다. InDesign의 .indb 파일은 읽거나 쓰지 않습니다.': 'The documents of the project are saved as a book. A book is in the Folio format (.foliobook) and remembers the project-relative path and the SHA-256 of each document. InDesign .indb files are not read or written.',
  '페이지 번호': 'Page numbers',
  '문서 시작 위치': 'Document starts',
  '빈 페이지 삽입': 'Insert blank page',
  '자동 페이지 번호 갱신': 'Automatic page numbering',
  '페이지 번호 갱신': 'Update page numbers',
  '문서를 더하거나 순서를 바꾸거나 빼면 번호를 다시 매깁니다. 번호를 매기면 책에 든 .folio 문서가 다시 저장되고, 다른 곳에서 열려 있는 문서가 있으면 아무것도 쓰지 않습니다.': 'Numbers are set again when a document is added, moved or removed. Numbering saves the .folio documents of the book again; if a document is open elsewhere, nothing is written.',
  '스타일 동기화': 'Synchronize styles',
  '스타일 기준 문서': 'Style source document',
  '첫 문서': 'First document',
  '책 동기화': 'Synchronize book',
  '기준 문서의 스타일이 다른 문서로 갑니다. 같은 이름은 기준 문서의 것으로 바뀌고, 없는 스타일은 더해지며, 그 문서에만 있는 스타일은 그대로 둡니다. 견본, 부모 페이지, 번호 매기기 목록, 조건, 텍스트 변수, 트랩 스타일, 목차 스타일, 상호 참조 형식은 아직 동기화하지 않습니다.': 'The styles of the source document go to the other documents. A style of the same name is replaced by the source\'s, a style the document lacks is added, and a style only the document has stays. Swatches, parent pages, numbered lists, conditions, text variables, trap styles, table of contents styles and cross-reference formats are not synchronized yet.',
  '동기화한 문서: {0}': 'Documents synchronized: {0}',
  '아직 없음: 책 전체 PDF 내보내기와 인쇄.': 'Not available yet: exporting the whole book to PDF and printing it.',
  '도형': 'Shape',
  '그림': 'Image',
  '최신순': 'Newest first',
  '오래된 순': 'Oldest first',
  '이름순': 'By name',
  '종류순': 'By type',
  '프로젝트 안에 로컬 라이브러리를 저장합니다. 라이브러리는 Folio 형식(.foliolibrary)이며 InDesign의 .indl 파일과 클라우드 라이브러리는 읽거나 쓰지 않습니다. 외부 링크가 없는 개체를 등록할 수 있습니다.': 'A local library is saved in the project. A library is in the Folio format (.foliolibrary); InDesign .indl files and cloud libraries are not read or written. Objects without external links can be stored.',
  '라이브러리 검색': 'Search library',
  '라이브러리 정렬': 'Sort library',
  '라이브러리 개체 레이블': 'Item label',
  '항목 정보 바꾸기': 'Change item information',
  '선택한 개체가 여러 개이면 하나의 항목으로 등록하고, 배치하면 그대로 여러 개가 놓입니다. 같은 이름의 색상과 스타일은 배치하는 문서의 것을 쓰고, 문서에 없는 스타일은 더해집니다.': 'Several selected objects are stored as one item and are placed as several objects. A color or style of the same name is taken from the document the item is placed in; a style the document lacks is added.',
  '아직 없음: 링크 그림이 있는 개체 등록과 링크 충돌 처리.': 'Not available yet: storing objects with linked pictures and handling link conflicts.',
  '책 전체 PDF 내보내기와 인쇄, 견본·부모 페이지·번호 매기기 목록 등의 책 동기화, 링크 그림이 있는 개체의 라이브러리 등록과 링크 충돌 처리': 'Exporting and printing a whole book as PDF, book synchronization of swatches, parent pages, numbered lists and the like, and storing objects with linked pictures in a library with link conflict handling',
  '패널 그룹 펼치기': 'Unfold panel group',
  '패널 그룹 접기': 'Fold panel group',
  '여기에 놓으면 패널이 이 열에 들어갑니다.': 'Drop here to put the panel in this column.',
  '링크 대상 주소가 비어 있습니다.': 'The link destination has no address.',
  '이 주소는 열 수 없습니다. 웹(http·https)과 메일(mailto) 주소만 열 수 있습니다: {url}': 'This address cannot be opened. Only web (http, https) and mail (mailto) addresses can be opened: {url}',
  '주소를 열지 못했습니다: {url}': 'Could not open the address: {url}',
  '대상 쪽을 찾을 수 없습니다.': 'The destination page was not found.',
  'GREP 스타일': 'GREP Styles',
  '정규식': 'Regular expression',
  'GREP 문자 스타일': 'GREP character style',
  'GREP 정규식': 'GREP expression',
  '규칙 추가': 'Add rule',
  '아래쪽 규칙이 같은 속성에서 우선합니다. 문자 스타일과 로컬 서식은 유지됩니다.': 'Later rules take precedence for the same property. Character styles and local formatting are retained.',
  '지원: 문자 클래스(\\d \\w \\s \\l \\u \\h, [[:alpha:]]), 한정자, 그룹, 앞뒤 탐색, 역참조, (?i), 앵커, ~ 특수 코드': 'Supported: character classes (\\d \\w \\s \\l \\u \\h, [[:alpha:]]), quantifiers, groups, look-around, back references, (?i), anchors, ~ special codes',
  '단락 스타일 전체에 적용: {name}': 'Applies to the entire paragraph style: {name}',
  '색인 만들기': 'Generate index',
  '색인 제목': 'Index title',
  '색인 글꼴': 'Index font',
  '묶음 머리글 포함': 'Include section headings',
  '기존 색인 교체': 'Replace existing index',
  '현재 쪽에 색인을 만듭니다. 모든 참조 범위, 상호 참조, 4단계 주제까지 지원합니다. 책 문서 포함을 켜면 이 문서가 든 책의 모든 문서 주제를 합칩니다.': 'Generate an index on the current page. Supports every reference range, cross-references and up to four topic levels. With Include book documents on, the topics of every document of the book that holds this document are merged.',
  '묶음 머리글 스타일': 'Section heading style',
