  '상호 참조 형식을 변경하지 못했습니다. 이름과 사용 여부를 확인하세요.': 'Could not change the cross-reference format. Check its name and whether it is in use.',
  '상호 참조 형식 편집': 'Edit cross-reference formats',
  '형식 편집…': 'Edit formats…',
  '구성 요소': 'Building block',
  '구성 요소 문자 스타일': 'Building block character style',
  '구분 문자': 'Delimiter',
  '구분 문자 포함': 'Include delimiter',
  '구성 요소 삭제': 'Remove building block',
  '구성 요소 추가': 'Add building block',
  '쪽 번호': 'Page number',
  '사용 중인 형식은 이름만 바꿀 수 있습니다. 구성 요소를 바꾸려면 먼저 복제하세요.': 'Only the name of a format in use can be changed. Duplicate it before changing its building blocks.',
  '혼합 문자 스타일 참조 업데이트, 형식·구성 요소 스타일의 중첩, 사용 중인 형식의 구성 요소 편집': 'Updating mixed character style references, combining format and block styles, and editing building blocks of formats in use',
  '혼합 문자 스타일 참조 업데이트와 형식·구성 요소 스타일의 중첩은 아직 지원하지 않습니다.': 'Updating mixed character style references and combining format and building block styles are not supported yet.',
'장 번호 {0}': 'Chapter {0}',
'장 번호 방식': 'Chapter numbering',
'선택 문서 장 번호 설정': 'Set selected document chapter number',
'페이지 번호를 갱신할 때 장 번호도 갱신합니다. 자동은 앞 문서의 장 번호에 1을 더하고, 직접 지정한 번호는 유지합니다.': 'Updating page numbers also updates chapters. Automatic chapters follow the previous document plus one; manual numbers stay unchanged.',
'직접 지정': 'Manual',
'책 전체 PDF 내보내기': 'Export whole book as PDF',
'저장된 문서를 책 순서대로 한 PDF로 내보냅니다. INDB/INDL 네이티브 호환은 하지 않습니다.': 'Exports saved documents in book order into one PDF. Native INDB/INDL compatibility is not supported.',
'책 PDF 상대 경로': 'Book PDF relative path',
'책 PDF 내보내기': 'Export book PDF',
'책 PDF 저장: {0}, {1}쪽': 'Book PDF saved: {0}, {1} pages',
  '인쇄용 PDF로 내보내기': 'Export a print-ready PDF',
  '견본': 'Swatches',
  '번호 매기기 목록': 'Numbered lists',
  '조건': 'Conditions',
  '트랩 스타일': 'Trap styles',
  '목차 스타일': 'Table of contents styles',
  "기준 문서의 같은 이름 정의로 바꾸고 새 정의를 더합니다. 대상 문서에만 있는 정의는 유지합니다. 견본([용지] 제외)·조건과 조건 집합·텍스트 변수·목차 스타일·상호 참조 형식을 모두 동기화합니다. 부모 페이지는 기본으로 꺼져 있고, 켜면 같은 이름의 부모 페이지를 기준 문서의 것으로 통째로 바꿉니다. 직접 지정한 조건 표시 색은 가져오지 않고, 두 문서에서 조건이 같은 자리에 있고 UI 색 조건의 수가 같을 때만 문서의 색이 남습니다.": "Replace definitions with the same name from the source and add new definitions. Keep definitions unique to the target. Swatches (except [Paper]), conditions and condition sets, text variables, table of contents styles and cross-reference formats are all synchronized. Parent pages are off by default; when switched on, a parent page with the same name is replaced by the source document's. Condition indicator colors you set yourself are not copied; the document keeps its own only when the condition stands in the same place in both documents and both hold as many conditions with a UI color up to there.",
  '링크 그림은 프로젝트 안에 복사합니다. 같은 이름의 다른 그림은 내용별로 따로 보관합니다.': 'Linked pictures are copied into the project. Different pictures with the same name are stored separately by content.',
  '그림 원본을 모두 찾을 수 있어야 등록할 수 있습니다.': 'All original pictures must be available before storing the asset.',
  '프로젝트 안에 로컬 라이브러리를 저장합니다. Folio 형식(.foliolibrary)이며 INDB/INDL 네이티브 호환과 클라우드 라이브러리는 지원하지 않습니다.': 'Save a local library in the project using the Folio format (.foliolibrary). Native INDB/INDL compatibility and cloud libraries are not supported.',
  "데이터 병합을 사용하려면 프로젝트 문서를 여세요.": "Open a project document to use Data Merge.",
  "프로젝트 상대 CSV/TXT 경로": "Project-relative CSV/TXT path",
