  "이미지 필드와 QR 코드 필드는 빈 사각형·타원·다각형을 선택한 뒤 삽입하세요.": "Select an empty rectangle, oval or polygon, then insert an image or QR code field.",
  '복합 효과 적용 인쇄·도형 효과 캡처·효과 범주별 해제·다음 문단 스타일': 'Printing applied combined effects, shape effect capture, disabling effect categories, and next paragraph styles',
  '텍스트 프레임의 효과 캡처와 문단 스타일 연결을 지원합니다. 복합 효과 적용 인쇄·도형 효과 캡처·효과 범주별 해제·다음 문단 스타일은 미완성입니다.': 'Effect capture from text frames and paragraph style links are supported. Printing applied combined effects, shape effect capture, disabling effect categories, and next paragraph styles are unfinished.',
