  '레이아웃 조정': 'Adjust Layout',
  '잠긴 개체도 조정': 'Allow locked objects to adjust',
  '모든 페이지와 부모 페이지를 새 크기로 바꾸고, 그 안의 개체를 늘리거나 줄입니다. 여백은 그대로 두거나 새로 정할 수 있고, 새 여백은 문서의 기본 여백과 같은 여백을 쓰는 부모 페이지와 그 부모를 따르는 페이지에 적용됩니다.': 'Resizes every page and parent page and stretches or shrinks the objects inside them. The margins can stay as they are or be set anew; new margins apply to the parent pages whose margins are the document\'s default margins and to the pages that follow those parents.',
