  'MathML 을 입력하면 여기에 수식이 나옵니다.': 'Type MathML and the equation appears here.',
  "설치된 수식 글꼴(OpenType MATH)을 찾지 못해 일반 글꼴 {0} 으로 근사해 조판했습니다.": "No installed math font (OpenType MATH) was found, so the equation was laid out approximately with the regular font {0}.",
