  '{0}쪽 · {1}pt': 'Page {0} · {1} pt',
  '설정과 페이지 할당을 바꿀 수 있습니다.': 'You can change the settings and the page assignment.',
  "트랩 설정과 페이지 할당은 문서에 저장되고 IDML 로 함께 내보냅니다. 분판 출력에 트랩을 그리는 기능은 지원하지 않습니다.": "Trap settings and page assignments are saved in the document and exported with the IDML. Drawing traps in separation output is not supported.",
  "Folio 는 PostScript 파일 대신 PDF 로 저장합니다. 책 전체를 프린터로 바로 보내는 기능은 지원하지 않으니 문서를 열어 인쇄하세요.": "Folio saves a PDF instead of a PostScript file. Sending the whole book straight to a printer is not supported; open the documents and print them.",
  "Folio 는 PostScript 대신 PDF 로 저장합니다. 분판·그래픽·색상 관리·고급 설정은 값만 저장하고 출력에는 쓰이지 않습니다. 프린터로 직접 보내기는 실제 프린터에서 확인하지 못했습니다.": "Folio saves a PDF instead of PostScript. Separations, graphics, color management and advanced settings are only stored; they do not change the output. Sending straight to a printer has not been checked on a real printer.",
  "Folio 는 소책자를 PostScript 대신 PDF 로 저장합니다. 프린터로 직접 보내기는 실제 프린터에서 확인하지 못했습니다.": "Folio saves the booklet as a PDF instead of PostScript. Sending straight to a printer has not been checked on a real printer.",
  "하이픈 사전은 영어·독일어·프랑스어·스페인어가 있습니다. 다른 언어의 글에는 하이픈을 넣지 않습니다.": "Hyphenation dictionaries are included for English, German, French and Spanish. Text in other languages is not hyphenated.",
  '이 링크는 프로젝트의 문서에 이을 수 없습니다': 'This link cannot be joined to a document of the project',
  '이 프로젝트에 {0}에서 가져온 문서가 없습니다. 그 문서를 먼저 프로젝트로 가져오세요': 'This project has no document imported from {0}. Import that document into the project first',
  '{0}에서 가져온 문서가 여러 개입니다. 이을 문서의 번호를 고르세요:\n{1}': 'Several documents were imported from {0}. Pick the number of the one to join to:\n{1}',
  '프로젝트 문서에 다시 연결': 'Relink to a project document',
  '링크 {0}개를 프로젝트의 문서에 이었습니다': 'Joined {0} links to the document of the project',
