  "책 패널 메뉴": "Book Panel Menu",
  "라이브러리 패널 메뉴": "Library Panel Menu",
  "책은 바뀔 때마다 바로 저장됩니다. 지금 저장된 상태입니다.": "The book is saved each time it changes. It is saved now.",
  "라이브러리는 목록으로 보입니다. 섬네일 보기는 지원하지 않습니다.": "The library is shown as a list. Thumbnail views are not supported.",
  "구역 지우기": "Delete Section",
  "문서의 첫 구역은 지울 수 없습니다": "The first section of a document cannot be deleted",
  "구역 시작 (오른쪽 단추: 구역 메뉴)": "Section start (right-click: Section menu)",
  "책 사전 검사": "Preflight Book",
  "책의 문서마다 사전 검사 패널과 같은 검사를 합니다. 문서는 이 창과 따로 열어 검사하므로 화면의 문서는 그대로입니다.": "Runs the Preflight panel's checks on each document of the book. Each document is opened apart from this window, so the document on screen stays as it is.",
  "책 사전 검사 결과": "Book preflight results",
