  "책 패키지를 만들 폴더": "Folder for the book package",
  "책 패키지 {0}개를 만들었습니다: {1}": "Made {0} book packages: {1}",
  "인쇄용 책 패키지": "Package Book For Print",
  "책의 문서마다 파일 ▸ 패키지와 같은 패키지(문서, 링크, 글꼴, 보고서)를 고른 폴더 안에 문서별 폴더로 만듭니다. 문서마다 따로 완결된 패키지입니다.": "Makes the same package as File ▸ Package (document, links, fonts, report) for each document of the book, in a folder of its own inside the folder you pick. Each package is complete on its own.",
