  "투명도·색을 그대로 둠 — 요즘 인쇄소 대부분, InDesign 기본": "Preserve transparency and color — widely accepted by printers, InDesign default",
  "CMYK·별색·오버프린트·투명도를 바꾸지 않고 그대로 둡니다(PDF 1.6).": "Preserves CMYK, spot colors, overprint, and transparency (PDF 1.6).",
  "투명도를 합치고 CMYK·별색만 — 인쇄소가 X-1a를 요구할 때": "Flatten transparency; CMYK and spot colors only — when your printer requires X-1a",
  "PDF 1.3. 투명도(불투명도·혼합 모드·그림자·페더 등)가 있는 곳만 잉크 그대로 그림으로 합칩니다(선·글자 1200 ppi, 나머지 300 ppi). 그 밖은 벡터·글자 그대로. RGB·Lab은 문서 CMYK로 바꾸고 CMYK 숫자는 그대로 둡니다.": "PDF 1.3. Flattens only areas with transparency (opacity, blending modes, shadows, feathering, etc.), preserving inks at 1200 ppi for line art and text and 300 ppi for other content. Other vectors and text are preserved. Converts RGB and Lab to document CMYK, preserving CMYK numbers.",
  "투명도를 합치고 색 관리된 RGB는 남김 — 인쇄소가 X-3을 요구할 때": "Flatten transparency; retain color-managed RGB — when your printer requires X-3",
  "PDF 1.3. 투명도가 있는 곳만 잉크 그대로 그림으로 합칩니다(선·글자 1200 ppi, 나머지 300 ppi). RGB는 프로파일을 붙여 그대로 둡니다.": "PDF 1.3. Flattens only transparent areas, preserving inks at 1200 ppi for line art and text and 300 ppi for other content. Preserves RGB with embedded profiles.",
