  "글의 가운데에서 시작 위치(1부터)와 개수로 가져옵니다.": "Takes characters from the middle by start (from 1) and count.",
  "글자 수를 셉니다.": "Counts the characters.",
  "영문을 대문자로 바꿉니다.": "Changes letters to upper case.",
  "영문을 소문자로 바꿉니다.": "Changes letters to lower case.",
  "앞뒤 공백을 지우고 가운데 공백은 하나로 줄입니다.": "Removes leading and trailing spaces and reduces inner spaces to one.",
  "글에서 찾는 글을 다른 글로 바꿉니다. 네 번째 값은 몇 번째만 바꿀지입니다.": "Replaces a text with another. The fourth value is which occurrence to replace.",
  "정규식으로 찾아 바꿉니다. 바꿀 글의 $1 은 첫 번째 묶음입니다.": "Finds and replaces with a regular expression. $1 in the replacement is the first group.",
  "구분자로 나눈 n번째 조각입니다. 1부터 세고, 음수는 뒤에서부터 셉니다.": "The nth piece split by a delimiter. Counts from 1, negative numbers from the end.",
  "조건이 참이면 앞의 값을, 아니면 뒤의 값을 씁니다. 뒤의 값을 빼면 빈 값입니다.": "Uses the first value when the condition is true, else the second. Empty without the second.",
  "조건과 값을 짝지어 적고 처음으로 참인 조건의 값을 씁니다.": "Pairs of condition and value; uses the value of the first true condition.",
  "모든 조건이 참이면 TRUE 입니다.": "TRUE when every condition is true.",
  "조건 하나라도 참이면 TRUE 입니다.": "TRUE when any condition is true.",
  "참과 거짓을 뒤집습니다.": "Reverses true and false.",
  "값이 비었거나 공백뿐이면 TRUE 입니다.": "TRUE when the value is empty or only spaces.",
  "값이 비었으면 대신할 값을 씁니다.": "Uses another value when the value is empty.",
  "글을 숫자로 바꿉니다. 1,234 와 12% 도 읽습니다.": "Turns a text into a number. Reads 1,234 and 12% too.",
  "숫자를 반올림합니다. 자릿수가 음수이면 10, 100 단위입니다.": "Rounds a number. Negative digits round to tens, hundreds.",
  "소수점 아래를 버려 정수로 만듭니다. 음수는 더 작은 쪽입니다.": "Drops the decimals to a whole number; negative numbers go down.",
  "절댓값입니다.": "The absolute value.",
  "숫자나 날짜를 서식에 맞춰 글로 바꿉니다.": "Turns a number or a date into text by a format.",
