  '비밀번호는 운영체제의 자격 증명 저장소에 저장되고 설정 파일이나 프로젝트에는 남지 않습니다. 저장하지 않으면 이 프로그램을 켜 둔 동안만 기억하고, 가져오기나 새로 고침에 비밀번호가 필요하면 그때 물어봅니다.': 'The password goes to the operating system\'s credential store and never into a settings file or the project. If you do not save it, it is remembered only while this program is running, and you are asked when an import or refresh needs it.',
  '이 컴퓨터에는 비밀번호 저장소가 없어 비밀번호를 저장하지 않습니다. 입력한 비밀번호는 이 프로그램을 켜 둔 동안만 기억하고, 필요하면 그때 물어봅니다.': 'This computer has no password store, so the password is not saved. A password you type is remembered only while this program is running, and you are asked when it is needed.',
  '비밀번호 저장소를 쓸 수 없습니다. 비밀번호를 저장하지 않고 이 세션 동안만 기억하게 하세요.': 'The password store cannot be used. Do not save the password; let the program remember it only while it is running.',
  '이 연결에는 비밀번호가 필요합니다. 비밀번호를 입력해 잠금을 푸세요.': 'This connection needs a password. Enter it to unlock the connection.',
  '비밀번호 입력': 'Enter Password',
  '비밀번호 입력…': 'Enter password…',
  '연결 "{0}" 의 비밀번호를 이 컴퓨터에 저장하지 않았습니다. 비밀번호를 입력하세요.': 'The password of the connection "{0}" is not saved on this computer. Enter the password.',
  '얼마 동안 기억할까요?': 'How long should it be remembered?',
  '이 프로그램을 켜 둔 동안만': 'Only while this program is running',
  '운영체제의 자격 증명 저장소에 저장': 'Save in the operating system\'s credential store',
  '비밀번호는 문서·설정 파일·기록에 남지 않습니다. 프로그램을 끄면 기억한 비밀번호를 잊습니다.': 'The password is not kept in the document, a settings file or any record. When you quit the program, the remembered password is forgotten.',
  '이 컴퓨터에는 비밀번호 저장소가 없어 이 프로그램을 켜 둔 동안만 기억합니다.': 'This computer has no password store, so the password is remembered only while this program is running.',
  '연결 "{0}" 을(를) 저장했고 비밀번호를 이 프로그램을 켜 둔 동안 기억합니다.': 'Saved the connection "{0}" and will remember its password while this program is running.',
  '연결 "{0}" 의 비밀번호를 잊었습니다.': 'Forgot the password of the connection "{0}".',
  '연결 "{0}" 의 비밀번호를 기억합니다.': 'Remembering the password of the connection "{0}".',
