  '기억한 비밀번호 잊기': 'Forget remembered password',
  '비밀번호 필요: 연결 "{0}" 의 비밀번호가 이 컴퓨터에 없어 데이터베이스에 닿지 못했습니다. 마지막으로 가져온 값으로 병합·인쇄합니다.': 'Password needed: this computer has no password for the connection "{0}", so the database could not be reached. Merging and printing use the values fetched last.',
