  '이 컴퓨터의 비밀번호 저장소에 버리는 시험 항목을 저장하고, 다시 읽고, 지운 뒤 남지 않았는지 확인합니다. 저장한 연결의 비밀번호는 건드리지 않습니다.': 'This keeps a throwaway test entry in the password store of this computer, reads it back, removes it and checks nothing is left. The passwords of saved connections are not touched.',
