  '시험을 실행하지 못했습니다: {0}': 'The test could not run: {0}',
  '다시 시험': 'Test Again',
  '이 컴퓨터에는 비밀번호 저장 도구(secret-tool, libsecret-tools 꾸러미)가 없어 비밀번호를 저장하지 않습니다. 입력한 비밀번호는 이 프로그램을 켜 둔 동안만 기억하고, 필요하면 그때 물어봅니다.': 'This computer has no password store tool (secret-tool, package libsecret-tools), so passwords are not saved. A password you type is remembered while this program runs and asked for again when needed.',
  'Android에서는 아직 비밀번호를 저장하지 않습니다(Android 키 저장소 연결이 아직 없습니다). 입력한 비밀번호는 이 프로그램을 켜 둔 동안만 기억하고, 필요하면 그때 물어봅니다.': 'Passwords are not saved on Android yet (the Android Keystore is not connected yet). A password you type is remembered while this program runs and asked for again when needed.',
