  '열린 프로젝트가 없습니다.': 'No project is open.',
  '지금 문서는 프로젝트 없이 읽기 전용으로 열었습니다. 고치려면 프로젝트로 가져오세요.': 'This document was opened read-only without a project. Import it into a project to edit it.',
  'Folio 는 폴더 하나를 프로젝트로 엽니다. 문서·책·라이브러리·그림이 모두 그 안에 있습니다.': 'Folio opens one folder as a project. Its documents, books, libraries and pictures are all inside it.',
