  '프로젝트 폴더가 비어 있습니다. 새 문서를 만들거나 InDesign 문서를 가져오세요.': 'The project folder is empty. Make a new document or import an InDesign document.',
  '문서 {0} · 파일 {1}': '{0} documents · {1} files',
  '읽지 못함': 'Unreadable',
  '없는 링크 {0}개 (가져올 때 없던 링크 {1}개 포함)': '{0} missing links ({1} already missing at import)',
  '이름 바꾸기는 책과 문서의 참조를 함께 고치는 엔진 명령이 아직 없어 여기서는 할 수 없습니다.': 'Renaming is not available here yet: there is no engine command that also updates the books and documents that refer to the file.',
  '지우기는 이 파일을 쓰는 문서·책을 확인하는 엔진 명령이 생기면 됩니다.': 'Deleting needs an engine command that first checks the documents and books using this file; there is none yet.',
