  "실행 취소된 단계나 처음 상태는 지울 수 없습니다.": "An undone step or the opening state cannot be deleted.",
  "뒤 단계가 이 단계에서 바꾼 것을 다시 바꿔서 이 단계만 지울 수 없습니다.": "A later step changed what this step changed, so this step cannot be deleted alone.",
