  "세로로 쓰는 텍스트 프레임을 만들고 글을 입력합니다.": "Creates vertical text frames and types into them.",
  "빈 곳에서 끌면 세로 텍스트 프레임을 만듭니다. 세로 글은 줄이 오른쪽에서 왼쪽으로 쌓이고 글자가 위에서 아래로 갑니다. 한글·한자는 똑바로 서고 로마자·숫자는 90° 돕니다. 글 안에서 ↑↓ 는 글자를, ←→ 는 줄을 옮깁니다. 이미 있는 글을 누르면 커서를 둡니다.": "Drag in an empty area to create a vertical text frame. Vertical lines run top to bottom and stack from right to left; Hangul and Han characters stand upright while Roman letters and digits turn 90°. In the text, Up and Down move by character and Left and Right move to the next or previous line. Click existing text to place the insertion point.",
