  '레이어 내보내기': 'Export Layers',
  '보이고 인쇄 가능한 레이어': 'Visible & Printable Layers',
  '하이퍼링크·책갈피 내보내기': 'Export hyperlinks and bookmarks',
  'PDF/X-1a·PDF/X-3(PDF 1.3)에는 Acrobat 레이어를 만들 수 없습니다. 레이어 내보내기는 담을 레이어를 고릅니다.': 'PDF/X-1a and PDF/X-3 (PDF 1.3) cannot hold Acrobat layers. Export Layers picks the layers that are written.',
  'Acrobat 레이어를 만들면 문서의 모든 레이어를 담고, 레이어 내보내기로 고른 레이어만 처음에 보입니다.': 'With Acrobat layers every layer of the document is written, and only the layers Export Layers picks are shown at first.',
  '내보낼 때 같은 이름 레이어 병합': 'Merge Identically Named Layers on Export',
