  '데이터 원본을 다시 읽어 병합이 넣은 글이 그대로인 필드만 새 값으로 바꿉니다. 손으로 고친 글과 다른 부분은 그대로 둡니다.': 'Reads the data source again and changes only the fields whose text is still what the merge put there. Text changed by hand and everything else stays as it is.',
