  '색인에 머리글 묶음으로 넣을 언어와 순서를 고릅니다. 고르지 않은 언어의 주제는 기호 묶음에 들어갑니다.': 'Choose the languages that get their own headed sections in the index, and their order. Topics in languages not chosen go in the Symbols section.',
