  "샘플이 포함된 Folio Studio를 다시 설치한 뒤 여세요.": "Reinstall Folio Studio with the samples included, then try again.",
  "문서 폴더에 파일을 만들 수 있는지와 남은 공간을 확인한 뒤 다시 여세요.": "Check that you can write to your Documents folder and have enough free space, then try again.",
  "샘플로 해 보기": "Try a sample",
  "이 잡지의 표지 제목을 더 짧게 바꿔 줘": "Shorten the cover headline of this magazine",
